    name: { de: "Zementwerk Opole", hu: "Opolei cementgyár", ro: "Fabrica de ciment Opole", en: "Opole Cement Works"},
    image: "/poi-images/poland-opole-cement-works-economic-v2.webp",
    coords: [17.922, 50.672],
